pub fn decrypt_rule(data: &[u8]) -> String {
    let decrypted: Vec<u8> = data.iter().map(|&b| b ^ XOR_KEY).collect();
    String::from_utf8_lossy(&decrypted).to_string()
}

#[allow(dead_code)]
pub fn encrypt_rule(text: &str) -> Vec<u8> {
    text.bytes().map(|b| b ^ XOR_KEY).collect()
}




